window.TECHLEX_DATA = window.TECHLEX_DATA || {};
window.TECHLEX_DATA["acad"] = [
{"w":"anecdotal","uk":"/ˌænɪkˈdəʊtl/","us":"/ˌænɪkˈdoʊtl/","pos":"adj.","cat":"acad-eval","en":"Based on individual reports rather than systematic evidence.","zh":"轶事性的：基于零散个例而非系统证据。","oe":"From Greek anekdota \"things unpublished\" (an- \"not\" + ekdotos \"given out\"). The word comes from the title Procopius gave his unpublished gossip about the court of Justinian.","oz":"源自希腊语 anekdota“未发表之事”（an- 未 + ekdotos 发布）。此词来自普罗柯比给自己那部关于查士丁尼宫廷的秘闻手稿所取的书名。","se":"Three happy users is anecdotal, not an evaluation.","sz":"三个满意用户属于轶事，不构成评测。","hw":1,"r":0},
{"w":"baseline","uk":"/ˈbeɪslaɪn/","us":"/ˈbeɪslaɪn/","pos":"n.","cat":"acad-meth","en":"The reference result that any new method must beat to be interesting.","zh":"基线：新方法必须超越、否则便无意义的参照结果。","oe":"From surveying, where a baseline is the first accurately measured line from which every other distance is triangulated.","oz":"源自测量学：基线是第一条精确丈量的线，其余所有距离都由它三角推算而来。","se":"A strong baseline is the cheapest way to kill a weak idea.","sz":"一个强基线是杀死弱想法最省钱的办法。","hw":1,"r":0},
{"w":"canonical","uk":"/kəˈnɒnɪkl/","us":"/kəˈnɑːnɪkl/","pos":"adj.","cat":"acad-eval","en":"The standard, authoritative form that others are compared against.","zh":"标准的／权威的：作为比较基准的那个规范形式。","oe":"From Greek kanon \"a measuring rod, a rule\", originally kanna \"a reed\" - the straight reed used as a ruler. The biblical canon is the list measured as authoritative.","oz":"源自希腊语 kanon“量尺、准则”，本义 kanna“芦苇”——用作直尺的那根笔直苇秆。《圣经》正典即被衡量为权威的书目。","se":"Always compare against the canonical implementation, not your rewrite.","sz":"永远和权威实现做对比，而不是和你自己重写的版本比。","hw":1,"r":0},
{"w":"caveat","uk":"/ˈkæviæt/","us":"/ˈkæviæt/","pos":"n.","cat":"acad-meth","en":"A stated limitation that qualifies a conclusion.","zh":"注意事项／限制说明：对结论加以限定的说明。","oe":"Latin for \"let him beware\", the subjunctive of cavere \"to take heed\" - as in caveat emptor, \"let the buyer beware\". A whole warning compressed into one verb.","oz":"拉丁语意为“让他当心”，是 cavere（当心）的虚拟式——如 caveat emptor“买者自慎”。一整句警告被压缩成一个动词。","se":"The result holds, with one important caveat about the test split.","sz":"这个结果成立，但关于测试集划分有一条重要的限制说明。","hw":1,"r":0},
{"w":"citation","uk":"/saɪˈteɪʃn/","us":"/saɪˈteɪʃn/","pos":"n.","cat":"acad-meth","en":"A formal reference to the source of a claim.","zh":"引用：对某个论断出处的正式标注。","oe":"From Latin citare \"to summon, to call forth\", a frequentative of ciere \"to set in motion\" - the same root as excite and incite. A citation summons a witness.","oz":"源自拉丁语 citare“传唤、召来”，是 ciere（使运动）的反复态——excite、incite 同根。引用就是传唤一位证人。","se":"A citation is not an argument; read the paper you cite.","sz":"引用不等于论证——请读一读你引用的那篇论文。","hw":1,"r":0},
{"w":"cogent","uk":"/ˈkəʊdʒənt/","us":"/ˈkoʊdʒənt/","pos":"adj.","cat":"acad-eval","en":"Clear and forceful enough to compel agreement.","zh":"有说服力的：清晰有力，令人不得不同意。","oe":"From Latin cogere \"to drive together, to compel\" (co- + agere \"to drive\") - the same cogere behind cogitate. A cogent argument herds you to its conclusion.","oz":"源自拉丁语 cogere“驱赶到一起、迫使”（co- + agere 驱动）——cogitate 同根。有说服力的论证会把你“赶”向它的结论。","se":"She gave the most cogent objection in the whole review.","sz":"整场评审中最有说服力的反对意见来自她。","hw":1,"r":0},
{"w":"cohort","uk":"/ˈkəʊhɔːt/","us":"/ˈkoʊhɔːrt/","pos":"n.","cat":"acad-meth","en":"A group sharing a defining characteristic, followed together through an analysis.","zh":"队列／群组：具有共同特征、被一同追踪分析的一批对象。","oe":"From Latin cohors \"an enclosure, a farmyard, then a company of soldiers\" - one tenth of a Roman legion. The same cohors gives us court and courtyard.","oz":"源自拉丁语 cohors“围栏、庭院，进而指一队士兵”——罗马军团的十分之一。court、courtyard 同源。","se":"Retention is only meaningful when read cohort by cohort.","sz":"留存率只有按群组分开来看才有意义。","hw":1,"r":0},
{"w":"confound","uk":"/kənˈfaʊnd/","us":"/kənˈfaʊnd/","pos":"v./n.","cat":"acad-meth","en":"A hidden variable that moves with both cause and effect, muddying the conclusion.","zh":"混杂因素：与因和果同时相关的隐藏变量，会搅浑结论。","oe":"From Latin confundere \"to pour together, to mix up\" (com- + fundere \"to pour\") - the same fundere behind fuse and refund. A confounder literally pours two causes into one.","oz":"源自拉丁语 confundere“倒在一起、混淆”（com- + fundere 倾倒）——fuse、refund 同根。混杂因素字面上就是把两个原因倒进了同一个杯子。","se":"Model size and data size are confounded in that comparison.","sz":"在那组对比中，模型规模与数据规模是相互混杂的。","hw":1,"r":0},
{"w":"contravene","uk":"/ˌkɒntrəˈviːn/","us":"/ˌkɑːntrəˈviːn/","pos":"v.","cat":"acad-verb","en":"To conflict with a rule, a law or an established finding.","zh":"违背：与某条规则、法律或既有结论相抵触。","oe":"From Latin contravenire \"to come against\" (contra + venire \"to come\") - the same venire as convene, intervene and provenance.","oz":"源自拉丁语 contravenire“迎面而来”（contra 相对 + venire 来）——convene、intervene、provenance 同根。","se":"The result appears to contravene the standard model.","sz":"这一结果似乎与标准模型相违背。","hw":1,"r":0},
{"w":"corroborate","uk":"/kəˈrɒbəreɪt/","us":"/kəˈrɑːbəreɪt/","pos":"v.","cat":"acad-verb","en":"To support a claim with independent evidence.","zh":"佐证：用独立的证据来支持某个论断。","oe":"From Latin corroborare \"to strengthen\" (com- + robur \"oak, hard timber\") - the same robur behind robust. To corroborate is to give a claim the strength of oak.","oz":"源自拉丁语 corroborare“加强”（com- + robur 橡木、硬木）——与 robust 同根。佐证就是给论断加上橡木般的强度。","se":"Two independent datasets corroborate the finding.","sz":"两份独立数据集佐证了这一发现。","hw":1,"r":0},
{"w":"criterion","uk":"/kraɪˈtɪəriən/","us":"/kraɪˈtɪriən/","pos":"n.","cat":"acad-meth","en":"A standard by which something is judged. Plural: criteria.","zh":"标准：判断事物的依据。复数为 criteria。","oe":"From Greek kriterion \"a means of judging\", from krinein \"to separate, to decide\" - the same krinein behind crisis, critic and discriminate.","oz":"源自希腊语 kriterion“判断的工具”，词根 krinein“分辨、裁定”——crisis、critic、discriminate 同根。","se":"State the stopping criterion before you look at the curve.","sz":"在看曲线之前先把停止标准定下来。","hw":1,"r":0},
{"w":"delineate","uk":"/dɪˈlɪnieɪt/","us":"/dɪˈlɪnieɪt/","pos":"v.","cat":"acad-verb","en":"To describe the boundaries of something precisely.","zh":"界定：精确地描述某事物的边界。","oe":"From Latin delineare \"to sketch out\" (de- + linea \"line\") - literally to draw the outline before filling it in.","oz":"源自拉丁语 delineare“勾勒轮廓”（de- + linea 线条）——字面意思是先画外框再填内容。","se":"Section 2 delineates the scope of the study.","sz":"第二节界定了本研究的范围。","hw":1,"r":0},
{"w":"disaggregate","uk":"/dɪsˈæɡrɪɡeɪt/","us":"/dɪsˈæɡrɪɡeɪt/","pos":"v.","cat":"acad-verb","en":"To break a total down into its component groups.","zh":"拆分：把一个总量分解成各个组成部分。","oe":"From Latin grex, gregis \"a flock\" - to aggregate is to herd together, so to disaggregate is to let the flock scatter again. Also behind gregarious and egregious.","oz":"源自拉丁语 grex/gregis“羊群”——aggregate 是把羊赶到一起，disaggregate 就是让羊群重新散开。gregarious、egregious 同源。","se":"Disaggregate the results by language before claiming parity.","sz":"在声称效果持平之前，先按语种把结果拆开看。","hw":1,"r":0},
{"w":"elucidate","uk":"/iˈluːsɪdeɪt/","us":"/iˈluːsɪdeɪt/","pos":"v.","cat":"acad-verb","en":"To make something clear by explaining it.","zh":"阐明：通过解释把某事说清楚。","oe":"From Latin elucidare (e- \"out\" + lucidus \"bright\"), from lux \"light\" - to bring a thing out into the light.","oz":"源自拉丁语 elucidare（e- 出 + lucidus 明亮），词根 lux“光”——把事物带到光亮之中。","se":"The ablation experiments elucidate why the model works.","sz":"消融实验阐明了模型有效的原因。","hw":1,"r":0},
{"w":"empirical","uk":"/ɪmˈpɪrɪkl/","us":"/ɪmˈpɪrɪkl/","pos":"adj.","cat":"acad-eval","en":"Based on observation or experiment rather than on theory alone.","zh":"实证的：基于观察或实验，而不仅仅基于理论。","oe":"From Greek empeirikos \"experienced\", from en- \"in\" + peira \"a trial, an attempt\" - the same peira behind experiment, expert and peril. The Empirics were an ancient school of physicians who trusted observation over doctrine.","oz":"源自希腊语 empeirikos“有经验的”，来自 en-（在内）+ peira（尝试、试验）——experiment、expert、peril 同根。古代“经验派”医生正是信观察而不信教条。","se":"The claim is theoretically appealing but empirically weak.","sz":"这个说法在理论上很动人，实证上却很弱。","hw":1,"r":0},
{"w":"extant","uk":"/ekˈstænt/","us":"/ˈekstənt/","pos":"adj.","cat":"acad-eval","en":"Still in existence; surviving.","zh":"现存的：至今仍然存在的。","oe":"From Latin exstare \"to stand out, to exist\" (ex- + stare \"to stand\"). Its opposite is extinct, not \"unextant\".","oz":"源自拉丁语 exstare“突出、存在”（ex- + stare 站立）。它的反义词是 extinct（灭绝的），而不是什么 unextant。","se":"None of the extant benchmarks measure that property.","sz":"现存的基准没有一个测量这一性质。","hw":1,"r":0},
{"w":"extrapolate","uk":"/ɪkˈstræpəleɪt/","us":"/ɪkˈstræpəleɪt/","pos":"v.","cat":"acad-verb","en":"To extend a trend beyond the range of the observed data.","zh":"外推：把某个趋势延伸到已观测数据范围之外。","oe":"Coined in the 1870s from Latin extra \"outside\" plus the ending of interpolate - reading beyond the table instead of between its rows.","oz":"1870 年代造词，取拉丁语 extra（之外）加上 interpolate 的词尾——在表格之外读数，而不是在行与行之间读数。","se":"Do not extrapolate a scaling law three orders of magnitude past your data.","sz":"不要把缩放定律外推到数据之外三个数量级。","hw":1,"r":0},
{"w":"germane","uk":"/dʒɜːˈmeɪn/","us":"/dʒɜːrˈmeɪn/","pos":"adj.","cat":"acad-eval","en":"Genuinely relevant to the matter at hand.","zh":"切题的：与当下讨论的问题确实相关。","oe":"A variant of german \"closely related by blood\" (Latin germanus \"of the same parents\"). Hamlet's line \"the phrase would be more german to the matter\" fixed the figurative sense in English.","oz":"是 german“有血缘近亲的”的变体（拉丁语 germanus“同父母的”）。《哈姆雷特》中那句“the phrase would be more german to the matter”定下了这一比喻义。","se":"That objection is interesting but not germane to the claim.","sz":"这个反驳很有意思，但与本文的论断并不切题。","hw":1,"r":0},
{"w":"longitudinal","uk":"/ˌlɒŋɡɪˈtjuːdɪnl/","us":"/ˌlɑːndʒəˈtuːdɪnl/","pos":"adj.","cat":"acad-meth","en":"Following the same subjects repeatedly over a long period.","zh":"纵向的：对同一批对象长期反复追踪观察。","oe":"From Latin longitudo \"length\" (longus \"long\"). A longitudinal study runs along time; a cross-sectional one cuts across it.","oz":"源自拉丁语 longitudo“长度”（longus 长）。纵向研究沿时间延伸，横断研究则横切时间。","se":"Only a longitudinal study can separate ageing from cohort effects.","sz":"只有纵向研究才能把年龄效应与世代效应分开。","hw":1,"r":0},
{"w":"methodology","uk":"/ˌmeθəˈdɒlədʒi/","us":"/ˌmeθəˈdɑːlədʒi/","pos":"n.","cat":"acad-meth","en":"The system of methods used in a study, and the reasoning for choosing them.","zh":"方法论：研究所采用的方法体系，以及选择这些方法的依据。","oe":"Greek methodos \"a pursuit of knowledge\" (meta \"after\" + hodos \"a way\") + logia \"study of\" - literally the study of ways of following after knowledge.","oz":"希腊语 methodos“求知之途”（meta 随后 + hodos 道路）+ logia（学问）——字面即“研究求知之路的学问”。","se":"The methodology section should let someone else rerun you.","sz":"方法论一节应当让别人能把你的实验重跑一遍。","hw":1,"r":0},
{"w":"mitigate","uk":"/ˈmɪtɪɡeɪt/","us":"/ˈmɪtɪɡeɪt/","pos":"v.","cat":"acad-verb","en":"To make something bad less severe, without removing it entirely.","zh":"缓解：减轻某种不利影响，但并未彻底消除。","oe":"From Latin mitigare \"to soften, to make mild\" (mitis \"mild\" + agere \"to drive\"). Note it is not militate, which means to weigh against.","oz":"源自拉丁语 mitigare“使温和”（mitis 温和 + agere 驱使）。注意它不是 militate（起反作用）。","se":"Dropout mitigates but does not eliminate overfitting.","sz":"Dropout 能缓解过拟合，但无法消除它。","hw":1,"r":0},
{"w":"nascent","uk":"/ˈnæsnt/","us":"/ˈnæsnt/","pos":"adj.","cat":"acad-eval","en":"Just coming into existence and not yet fully formed.","zh":"新兴的：刚刚出现、尚未成形。","oe":"From Latin nasci \"to be born\" - the same root as nature, native, innate and renaissance.","oz":"源自拉丁语 nasci“出生”——nature、native、innate、renaissance 同根。","se":"The field was nascent when the first benchmark appeared.","sz":"第一个基准出现时，这个领域尚属新兴。","hw":1,"r":0},
{"w":"obviate","uk":"/ˈɒbvieɪt/","us":"/ˈɑːbvieɪt/","pos":"v.","cat":"acad-verb","en":"To remove the need for something by anticipating it.","zh":"免除：通过预先处理，让某件事变得不再必要。","oe":"From Latin obviare \"to meet in the way\" (ob- \"against\" + via \"road\") - to go out and meet a difficulty on the road, so it never arrives. Obvious shares the same road.","oz":"源自拉丁语 obviare“在路上迎面挡住”（ob- 相对 + via 道路）——迎上去把麻烦挡在路上，它便到不了。obvious 走的也是这条 via。","se":"Caching obviates the need for a second round trip.","sz":"有了缓存，就免去了第二次往返请求。","hw":1,"r":0},
{"w":"orthogonal","uk":"/ɔːˈθɒɡənl/","us":"/ɔːrˈθɑːɡənl/","pos":"adj.","cat":"acad-eval","en":"Independent; varying one has no effect on the other.","zh":"正交的／互不相干的：改变其中一个不会影响另一个。","oe":"Greek orthos \"straight, right\" + gonia \"angle\" - at right angles. Engineers stretched the geometric sense into \"unrelated\", which is now the commoner use in a design discussion.","oz":"希腊语 orthos（直、正）+ gonia（角）——成直角。工程师把这个几何义引申为“互不相干”，如今在设计讨论中反而更常用。","se":"Those two concerns are orthogonal; solve them separately.","sz":"这两个问题是正交的，分开解决就好。","hw":1,"r":0},
{"w":"ostensible","uk":"/ɒˈstensəbl/","us":"/ɑːˈstensəbl/","pos":"adj.","cat":"acad-eval","en":"Stated as the reason, though possibly not the real one.","zh":"表面上的：被声称为理由，但未必是真正的理由。","oe":"From Latin ostendere \"to show, to display\" (obs- \"towards\" + tendere \"to stretch\") - the same tendere as attention. What is stretched out for show may not be what is inside.","oz":"源自拉丁语 ostendere“展示”（obs- 朝向 + tendere 伸展）——与 attention 同根。摆出来给人看的，未必就是里头的东西。","se":"The ostensible reason was latency; the real one was cost.","sz":"表面上的理由是延迟，真正的理由是成本。","hw":1,"r":0},
{"w":"paradigm","uk":"/ˈpærədaɪm/","us":"/ˈpærədaɪm/","pos":"n.","cat":"acad-meth","en":"The set of assumptions and practices a research community currently works inside.","zh":"范式：某个研究共同体当下共同接受的假设与实践框架。","oe":"From Greek paradeigma \"a pattern, an example\" (para \"beside\" + deiknynai \"to show\"). Thomas Kuhn gave it its modern weight in 1962 with the phrase \"paradigm shift\".","oz":"源自希腊语 paradeigma“范例、样板”（para 旁边 + deiknynai 展示）。1962 年托马斯·库恩以“范式转移”一语赋予它现代分量。","se":"Pretraining then fine-tuning became the dominant paradigm.","sz":"先预训练再微调成为了主导范式。","hw":1,"r":0},
{"w":"parsimonious","uk":"/ˌpɑːsɪˈməʊniəs/","us":"/ˌpɑːrsɪˈmoʊniəs/","pos":"adj.","cat":"acad-eval","en":"Explaining as much as possible with as few assumptions as possible.","zh":"简约的：用尽可能少的假设解释尽可能多的现象。","oe":"From Latin parsimonia \"thrift\", from parcere \"to spare\". In science the word carries no stinginess - the law of parsimony is Occam's razor.","oz":"源自拉丁语 parsimonia“节俭”，词根 parcere“节省”。在科学语境中它并无吝啬之意——简约律即奥卡姆剃刀。","se":"Prefer the more parsimonious explanation when both fit.","sz":"两种解释都说得通时，取更简约的那个。","hw":1,"r":0},
{"w":"plausible","uk":"/ˈplɔːzəbl/","us":"/ˈplɔːzəbl/","pos":"adj.","cat":"acad-eval","en":"Believable on the face of it, whether or not it is true.","zh":"看似合理的：表面上说得通，未必为真。","oe":"From Latin plausibilis \"deserving applause\", from plaudere \"to clap\" - also behind applaud and explode, which once meant to drive an actor off stage by clapping. A plausible claim is one the audience would clap for.","oz":"源自拉丁语 plausibilis“值得鼓掌的”，词根 plaudere“拍手”——applaud 同源；explode 也同源，本义是“用掌声把演员轰下台”。看似合理的说法，就是观众愿意为之鼓掌的说法。","se":"Fluent output makes a wrong answer sound plausible.","sz":"流畅的输出会让错误答案听起来很合理。","hw":1,"r":0},
{"w":"posit","uk":"/ˈpɒzɪt/","us":"/ˈpɑːzɪt/","pos":"v.","cat":"acad-verb","en":"To put forward as a basis for argument, without yet proving it.","zh":"假定／提出：先摆出某个前提作为论证基础，暂不加以证明。","oe":"From Latin ponere, past participle positus, \"to place, to put\" - the same root as position, deposit and compose.","oz":"源自拉丁语 ponere（过去分词 positus）“放置”——position、deposit、compose 同根。","se":"We posit that the gain comes from data diversity.","sz":"我们假定这一提升来自数据的多样性。","hw":1,"r":0},
{"w":"preclude","uk":"/prɪˈkluːd/","us":"/prɪˈkluːd/","pos":"v.","cat":"acad-verb","en":"To make something impossible in advance.","zh":"排除／使不可能：事先就堵死某种可能。","oe":"From Latin praecludere \"to close off beforehand\" (prae- \"before\" + claudere \"to shut\") - the same claudere behind close, conclude and exclude.","oz":"源自拉丁语 praecludere“事先关闭”（prae- 之前 + claudere 关）——close、conclude、exclude 同根。","se":"A small sample does not preclude a strong effect.","sz":"样本量小并不排除存在强效应的可能。","hw":1,"r":0},
{"w":"rationale","uk":"/ˌræʃəˈnɑːl/","us":"/ˌræʃəˈnæl/","pos":"n.","cat":"acad-meth","en":"The stated reasoning behind a choice or a design.","zh":"理据：某个选择或设计背后所陈述的理由。","oe":"From Latin rationalis, from ratio \"a reckoning, a calculation, a reason\" - originally an accountant's word, from reri \"to reckon\".","oz":"源自拉丁语 rationalis，词根 ratio“计算、账目、理由”——本是会计用词，动词 reri“计算”。","se":"Write the rationale down; in six months nobody will remember it.","sz":"把设计理据写下来，半年后没人记得住。","hw":1,"r":0},
{"w":"reconcile","uk":"/ˈrekənsaɪl/","us":"/ˈrekənsaɪl/","pos":"v.","cat":"acad-verb","en":"To show how two apparently conflicting findings can both be true.","zh":"调和：说明两项看似矛盾的发现如何能同时成立。","oe":"From Latin reconciliare \"to bring together again\" (re- + conciliare \"to unite\", from concilium \"a council\") - people summoned back into the same room.","oz":"源自拉丁语 reconciliare“重新聚拢”（re- + conciliare 联合，词根 concilium 会议）——把人重新召回同一个房间。","se":"The paper reconciles the two conflicting benchmarks.","sz":"这篇论文调和了两个相互冲突的基准结果。","hw":1,"r":0},
{"w":"reproducibility","uk":"/ˌriːprəˌdjuːsəˈbɪləti/","us":"/ˌriːprəˌduːsəˈbɪləti/","pos":"n.","cat":"acad-meth","en":"Whether an independent team can obtain the same result from the same description.","zh":"可复现性：独立团队能否依据同样的描述得到同样的结果。","oe":"From Latin producere \"to lead forth\" (pro- + ducere \"to lead\") - the same ducere as conduct, deduce and educate.","oz":"源自拉丁语 producere“引出”（pro- + ducere 引导）——conduct、deduce、educate 同根。","se":"Release the seeds and the config, or reproducibility is a slogan.","sz":"把随机种子和配置一并发布，否则可复现性只是个口号。","hw":1,"r":0},
{"w":"rigorous","uk":"/ˈrɪɡərəs/","us":"/ˈrɪɡərəs/","pos":"adj.","cat":"acad-eval","en":"Carried out with strict, unforgiving care for correctness.","zh":"严谨的：以严格、不容含糊的方式确保正确性。","oe":"From Latin rigor \"stiffness, numbness\" - the same rigor as in rigor mortis. A rigorous proof does not bend.","oz":"源自拉丁语 rigor“僵硬、麻木”——rigor mortis（尸僵）中的正是此词。严谨的证明是不弯折的。","se":"The evaluation is thorough but not rigorous.","sz":"这套评测很全面，但称不上严谨。","hw":1,"r":0},
{"w":"scrutinize","uk":"/ˈskruːtɪnaɪz/","us":"/ˈskruːtənaɪz/","pos":"v.","cat":"acad-verb","en":"To examine something closely and critically.","zh":"细察：对某事物做仔细而挑剔的检查。","oe":"From Latin scrutari \"to search, to examine\", originally \"to sort through rags\", from scruta \"trash, old rags\" - the rag-picker's thoroughness.","oz":"源自拉丁语 scrutari“搜查、细看”，本义是“翻拣破布”，词根 scruta“破烂、旧布”——拾荒者式的细致。","se":"Reviewers scrutinized the evaluation protocol, not the model.","sz":"审稿人细察的是评测方案，而不是模型本身。","hw":1,"r":0},
{"w":"seminal","uk":"/ˈsemɪnl/","us":"/ˈsemɪnl/","pos":"adj.","cat":"acad-eval","en":"Describing early work from which a whole line of later research grew.","zh":"开创性的：指后来一整条研究脉络由之生发的早期工作。","oe":"From Latin semen \"seed\" - a seminal paper is one that seeds a field. Same root as seminar, disseminate and semester's cousin seminary.","oz":"源自拉丁语 semen“种子”——开创性论文即为一个领域播下种子。seminar、disseminate、seminary 同源。","se":"The 2017 attention paper is by now genuinely seminal.","sz":"2017 年那篇注意力论文如今确实称得上开创性。","hw":1,"r":0},
{"w":"significance","uk":"/sɪɡˈnɪfɪkəns/","us":"/sɪɡˈnɪfɪkəns/","pos":"n.","cat":"acad-meth","en":"In statistics, how unlikely the observed result would be if nothing were going on.","zh":"显著性：在统计上，若实际并无效应，观测到该结果的可能性有多低。","oe":"From Latin significare \"to make a sign\" (signum \"sign\" + facere \"to make\"). Beware: statistical significance and practical importance are different things.","oz":"源自拉丁语 significare“做出标记”（signum 符号 + facere 制造）。注意：统计显著与实际重要并不是一回事。","se":"Significance is not effect size, and neither is importance.","sz":"显著性不等于效应量，也不等于重要性。","hw":1,"r":0},
{"w":"spurious","uk":"/ˈspjʊəriəs/","us":"/ˈspjʊriəs/","pos":"adj.","cat":"acad-eval","en":"Looking real but produced by an artefact of the data rather than by the effect studied.","zh":"虚假的：看起来真实，实则由数据的假象而非所研究的效应产生。","oe":"From Latin spurius \"illegitimate, of uncertain father\". A spurious correlation is one with no legitimate parent.","oz":"源自拉丁语 spurius“私生的、父不详的”。虚假相关就是没有正当来源的相关。","se":"The classifier learned a spurious correlation with image background.","sz":"这个分类器学到的是与图像背景之间的虚假相关。","hw":1,"r":0},
{"w":"substantiate","uk":"/səbˈstænʃieɪt/","us":"/səbˈstænʃieɪt/","pos":"v.","cat":"acad-verb","en":"To back a claim up with enough evidence to make it stand.","zh":"证实：拿出足够证据让某个论断站得住。","oe":"From Latin substantia \"substance\", literally \"that which stands under\" (sub- + stare \"to stand\"). To substantiate is to put something solid underneath.","oz":"源自拉丁语 substantia“实体”，字面为“立于其下之物”（sub- + stare 站立）。证实就是在底下垫上实在的东西。","se":"The claim is interesting but not yet substantiated.","sz":"这个论断很有意思，但尚未得到证实。","hw":1,"r":0},
{"w":"supersede","uk":"/ˌsuːpəˈsiːd/","us":"/ˌsuːpərˈsiːd/","pos":"v.","cat":"acad-verb","en":"To take the place of something older, which is thereby retired.","zh":"取代：替换掉更早的版本，后者随之退场。","oe":"From Latin supersedere \"to sit above, to refrain from\" (super + sedere \"to sit\"). Note the spelling: -sede, not -cede, because it is sedere \"to sit\", not cedere \"to go\".","oz":"源自拉丁语 supersedere“高居其上、不再进行”（super 之上 + sedere 坐）。注意拼写是 -sede 而非 -cede，因为词根是 sedere（坐）而不是 cedere（走）。","se":"RFC 8446 supersedes the TLS 1.2 specification.","sz":"RFC 8446 取代了 TLS 1.2 的规范。","hw":1,"r":0},
{"w":"synthesis","uk":"/ˈsɪnθəsɪs/","us":"/ˈsɪnθəsɪs/","pos":"n.","cat":"acad-meth","en":"Combining separate findings into one coherent account.","zh":"综合：把分散的发现整合成一个自洽的整体解释。","oe":"Greek syntithenai \"to put together\" (syn + tithenai \"to place\") - the same tithenai behind thesis and hypothesis.","oz":"希腊语 syntithenai“放到一起”（syn + tithenai 放置）——thesis、hypothesis 同根。","se":"The last section is a synthesis, not a summary.","sz":"最后一节是综合，而不是简单的总结。","hw":1,"r":0},
{"w":"taxonomy","uk":"/tækˈsɒnəmi/","us":"/tækˈsɑːnəmi/","pos":"n.","cat":"acad-meth","en":"A structured scheme of classification.","zh":"分类体系：有结构的分类方案。","oe":"Greek taxis \"arrangement, order\" + nomia \"distribution, law\" - the same taxis behind tactics and syntax.","oz":"希腊语 taxis（排列、秩序）+ nomia（分配、法则）——tactics、syntax 中的 taxis 同根。","se":"A taxonomy of failures is worth more than a list of them.","sz":"一套故障分类体系，比一张故障清单有价值得多。","hw":1,"r":0},
{"w":"tenuous","uk":"/ˈtenjuəs/","us":"/ˈtenjuəs/","pos":"adj.","cat":"acad-eval","en":"Weak, thin, resting on very little support.","zh":"站不住脚的：薄弱、缺乏支撑。","oe":"From Latin tenuis \"thin, slender\" - the same root as attenuation and, through Germanic, English thin itself.","oz":"源自拉丁语 tenuis“细薄”——与 attenuation 同根，经日耳曼语支也与英语 thin 同源。","se":"The link between the two datasets is tenuous at best.","sz":"这两份数据集之间的关联充其量也很牵强。","hw":1,"r":0},
{"w":"underpin","uk":"/ˌʌndəˈpɪn/","us":"/ˌʌndərˈpɪn/","pos":"v.","cat":"acad-verb","en":"To provide the foundation that something else rests on.","zh":"支撑：为其他结论提供赖以成立的基础。","oe":"A builder's term: to insert supports beneath an existing wall so it does not settle. The metaphor kept the picture exactly.","oz":"建筑术语：在既有墙体下方加设支撑，防止沉降。这个比喻完整保留了原本的画面。","se":"Three assumptions underpin the whole argument.","sz":"整个论证由三条假设支撑。","hw":1,"r":0},
{"w":"verbatim","uk":"/vɜːˈbeɪtɪm/","us":"/vɜːrˈbeɪtɪm/","pos":"adv./adj.","cat":"acad-meth","en":"Word for word, exactly as originally written or said.","zh":"逐字地：与原文或原话一字不差。","oe":"Latin verbatim \"word for word\", from verbum \"word\" - the same verbum behind verb, verbal and proverb.","oz":"拉丁语 verbatim“逐字”，词根 verbum“词”——verb、verbal、proverb 同源。","se":"Quote the error verbatim; paraphrasing loses the clue.","sz":"把报错原文照抄下来，转述会丢掉线索。","hw":1,"r":0}
];
